describe('Table Row Highlighting', () => {
  beforeEach(() => {
    cy.visit('/table-list');
  });

  it('should highlight selected rows with a different colour', () => {
    // Verify table is visible
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Verify initial row state
    cy.get('[data-testid="table-row-1"]').should('have.css', 'background-color', 'transparent');

    // Click on the first row to select it
    cy.get('[data-testid="table-row-1"]').click();

    // Verify first row is highlighted
    cy.get('[data-testid="table-row-1"]').should('have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');

    // Verify second row is not highlighted
    cy.get('[data-testid="table-row-2"]').should('have.css', 'background-color', 'transparent');

    // Click on the second row to select it
    cy.get('[data-testid="table-row-2"]').click();

    // Verify second row is highlighted
    cy.get('[data-testid="table-row-2"]').should('have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');

    // Verify first row is no longer highlighted
    cy.get('[data-testid="table-row-1"]').should('not.have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');

    // Verify table row data is still visible
    cy.get('[data-testid="table-row-1"]').should('contain', 'Row 1 Data');

    // Verify row selection is cleared when clicking on a non-selected row
    cy.get('[data-testid="table-row-3"]').click();

    // Verify only the third row is highlighted
    cy.get('[data-testid="table-row-3"]').should('have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');

    // Verify other rows are not highlighted
    cy.get('[data-testid="table-row-1"]').should('not.have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');
    cy.get('[data-testid="table-row-2"]').should('not.have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');
  });

  it('should not highlight rows when clicking on disabled or non-selectable elements', () => {
    // Verify table is visible
    cy.get('[data-testid="table-container"]').should('be.visible');

    // Verify first row is highlighted
    cy.get('[data-testid="table-row-1"]').should('have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');

    // Click on a disabled row (e.g., row with data-testid="table-row-disabled")
    cy.get('[data-testid="table-row-disabled"]').click();

    // Verify disabled row is not highlighted
    cy.get('[data-testid="table-row-disabled"]').should('not.have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');

    // Verify other rows remain highlighted
    cy.get('[data-testid="table-row-1"]').should('have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');
    cy.get('[data-testid="table-row-2"]').should('have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');

    // Verify clicking on a non-selectable element (e.g., row with data-testid="table-row-non-selectable")
    cy.get('[data-testid="table-row-non-selectable"]').click();

    // Verify non-selectable row is not highlighted
    cy.get('[data-testid="table-row-non-selectable"]').should('not.have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');

    // Verify other rows remain highlighted
    cy.get('[data-testid="table-row-1"]').should('have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');
    cy.get('[data-testid="table-row-2"]').should('have.css', 'background-color', 'rgba(255, 255, 0, 0.2)');
  });
});
